import {SETTINGS} from './service-defaults.mjs';
import {projects as originalProjects} from './cms/portfolio-data.mjs';
const json=(v,status=200)=>new Response(JSON.stringify(v),{status,headers:{'Content-Type':'application/json','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
const str=(v,n=2000)=>typeof v==='string'?v.trim().slice(0,n):'';
const safeURL=v=>typeof v==='string'&&!/[\s<>"']/ .test(v)&&(/^(\/satin\/|\/api\/service-asset\?id=[a-f0-9-]{36}$)/.test(v)||/^https:\/\/(?:sinalite\.com|www\.sinalite\.com)\//.test(v));
export async function serviceSettings(db){const r=await db.prepare('SELECT value FROM site_settings WHERE key = ?').bind('services_v2').first();return {...SETTINGS,...(r?JSON.parse(r.value):{})};}
export async function projectRecords(db){const r=await db.prepare('SELECT value FROM site_settings WHERE key = ?').bind('portfolio_v2').first();return r?JSON.parse(r.value):originalProjects;}
async function save(db,k,v){await db.prepare('INSERT INTO site_settings (key,value,updated_at) VALUES (?,?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at').bind(k,JSON.stringify(v),new Date().toISOString()).run();}
export async function bookingSlots(db,date){const s=await serviceSettings(db);if(!/^\d{4}-\d{2}-\d{2}$/.test(date))return [];const d=new Date(date+'T12:00:00Z');if(!Number.isFinite(d.getTime())||d.toISOString().slice(0,10)!==date||s.closedDates.includes(date)||!s.bookingDays.includes(d.getUTCDay()))return [];const today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Toronto',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());if(date<today)return [];const time=new Intl.DateTimeFormat('en-GB',{timeZone:'America/Toronto',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date());const booked=await db.prepare("SELECT preferred_time FROM service_requests WHERE type = 'booking' AND preferred_date = ? AND status = 'confirmed'").bind(date).all();return s.bookingTimes.filter(t=>(date!==today||t>time)&&!booked.results.some(b=>b.preferred_time===t));}
export async function serviceRoutes(request,env,url,isAdmin){const p=url.pathname;if(!['/api/service-settings','/api/admin/service-settings','/api/projects','/api/admin/projects','/api/admin/service-upload','/api/service-asset','/api/booking-slots'].includes(p))return null;
const admin=isAdmin(request);if(p.startsWith('/api/admin/')&&!admin)return json({error:'Owner sign-in required'},403);if(!['GET','POST'].includes(request.method))return json({error:'Method not allowed'},405);if(request.method==='POST'&&(!admin||!p.startsWith('/api/admin/')||request.headers.get('Origin')!==url.origin))return json({error:'Forbidden'},403);if(!env.DB)return json({error:'Storage unavailable'},503);
try{if(p==='/api/booking-slots')return json({slots:await bookingSlots(env.DB,url.searchParams.get('date')||''),timezone:'America/Toronto'});
if(p==='/api/service-asset'){const id=url.searchParams.get('id');if(!/^[a-f0-9-]{36}$/.test(id||''))return json({error:'Not found'},404);const published=JSON.stringify([await serviceSettings(env.DB),(await projectRecords(env.DB)).filter(x=>x.active!==false),JSON.parse((await env.DB.prepare('SELECT value FROM site_settings WHERE key = ?').bind('product_catalog').first())?.value||'[]').filter(x=>x.active!==false)]);if(!admin&&!published.includes('/api/service-asset?id='+id))return json({error:'Not found'},404);const o=await env.FILES?.get('services/'+id);if(!o)return json({error:'Not found'},404);return new Response(o.body,{headers:{'Content-Type':o.httpMetadata.contentType,'Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Content-Disposition':o.httpMetadata.contentType.startsWith('image/')?'inline':'attachment; filename="template.'+(o.httpMetadata.contentType==='application/pdf'?'pdf':'zip')+'"'}});}
if(p==='/api/admin/service-upload'){if(request.method!=='POST')return json({error:'Use POST'},405);if(!env.FILES)return json({error:'Upload storage unavailable'},503);const reader=request.body.getReader(),chunks=[];let count=0;while(true){const {done,value}=await reader.read();if(done)break;count+=value.length;if(count>21000000){await reader.cancel();throw Error('Maximum upload is 20 MB');}chunks.push(value);}const raw=new Uint8Array(count);let offset=0;for(const b of chunks){raw.set(b,offset);offset+=b.length;}const fd=await new Response(raw,{headers:{'Content-Type':request.headers.get('Content-Type')}}).formData(),file=fd.get('file');if(!file||file.size>20000000||file.size<8)throw Error('Choose a file up to 20 MB');const b=new Uint8Array(await file.arrayBuffer()),head=new TextDecoder().decode(b.slice(0,12));const type=b[0]===137&&head.slice(1,4)==='PNG'?'image/png':b[0]===255&&b[1]===216?'image/jpeg':head.startsWith('RIFF')&&head.slice(8)==='WEBP'?'image/webp':head.startsWith('%PDF-')?'application/pdf':head.startsWith('PK')?'application/zip':'';if(!type)throw Error('Use PNG, JPG, WebP, PDF or ZIP');const id=crypto.randomUUID();await env.FILES.put('services/'+id,b,{httpMetadata:{contentType:type}});return json({url:'/api/service-asset?id='+id,name:str(file.name,120),type},201);}
if(request.method==='GET'){if(p.endsWith('projects'))return json({projects:(await projectRecords(env.DB)).filter(x=>admin||x.active!==false)});return json(await serviceSettings(env.DB));}
const raw=await request.text();if(raw.length>2000000)throw Error('Request too large');const v=JSON.parse(raw);
if(p.endsWith('projects')){const items=await projectRecords(env.DB),x=v.project;if(!x||!/^[-a-z0-9]{2,120}$/.test(x.slug)||!str(x.title)||!['commercial','colour'].includes(x.category)||!Array.isArray(x.images)||!x.images.length||x.images.length>40)throw Error('Add a title, category and 1–40 photos');for(const im of x.images)if(!safeURL(im.src))throw Error('Use uploaded or site photos');const value={id:str(x.id,120)||crypto.randomUUID(),slug:x.slug,title:str(x.title,160),category:x.category,vehicle:str(x.vehicle,60),industry:str(x.industry,80),coverage:str(x.coverage,80),description:str(x.description,5000),tags:[x.vehicle,x.coverage,x.industry].filter(Boolean).map(t=>str(t,80)),active:x.active!==false,images:x.images.map(im=>({src:im.src,alt:str(im.alt,200)||str(x.title),width:1200,height:800}))};value.cover=value.images[0];const i=items.findIndex(p=>p.id===value.id);if(items.some(p=>p.id!==value.id&&p.slug===value.slug))throw Error('Project address already exists');if(i<0)items.unshift(value);else items[i]=value;await save(env.DB,'portfolio_v2',items);return json({saved:true});}
if('promotions' in v){if(!Array.isArray(v.promotions)||v.promotions.length>12||v.promotions.some(p=>!str(p.title,160)||!safeURL(p.image)||!/^\/satin(?:\/|$)/.test(p.link)))throw Error('Check promotion title, image and button link');}
const old=await serviceSettings(env.DB),out={...old};
if(v.promotionDisplay){const x=v.promotionDisplay;if(!Number.isFinite(x.intervalSeconds)||x.intervalSeconds<3||x.intervalSeconds>60||!/^#[a-f0-9]{6}$/i.test(x.background)||!/^#[a-f0-9]{6}$/i.test(x.textColor))throw Error('Check promotion colours and slide interval');out.promotionDisplay={intervalSeconds:x.intervalSeconds,autoplay:x.autoplay!==false,background:x.background,textColor:x.textColor};}
if(v.videoPartner){const x=v.videoPartner;if(!Array.isArray(x.plans)||x.plans.length>12)throw Error('Check video plans');out.videoPartner={title:str(x.title,160),text:str(x.text,1000),plans:x.plans.map(p=>({name:str(p.name,160),price:str(p.price,160),detail:str(p.detail,1000)}))};}
for(const k of ['designEmail','designTerms','installationTerms','bookingNote','filePrep','fileGuide','wallGuide','detailingIntro','detailingAftercare'])if(k in v)out[k]=str(v[k],k.endsWith('Terms')?20000:5000);if(out.fileGuide&&!safeURL(out.fileGuide))throw Error('Use an uploaded or Sinalite guide link');if(!/^\S+@\S+\.\S+$/.test(out.designEmail))throw Error('Check design email');
if('promotions' in v)out.promotions=v.promotions.map(p=>({title:str(p.title,160),text:str(p.text,600),button:str(p.button,80),link:p.link,image:p.image,active:p.active!==false}));
for(const k of ['bookingDays','bookingTimes','closedDates','detailingPlans','ppfPlans','ppfBrands'])if(k in v){if(!Array.isArray(v[k])||v[k].length>366)throw Error('Check '+k);out[k]=v[k];}
if(out.bookingDays.some(n=>!Number.isInteger(n)||n<0||n>6)||out.bookingTimes.some(t=>!/^([01]\d|2[0-3]):[0-5]\d$/.test(t))||out.closedDates.some(t=>!/^\d{4}-\d{2}-\d{2}$/.test(t)))throw Error('Check schedule');
for(const k of ['printBanner','wallBanner'])if(k in v){if(!safeURL(v[k].image)||k==='printBanner'&&!/^\/satin\//.test(v[k].link))throw Error('Check banner image or link');out[k]={title:str(v[k].title,160),text:str(v[k].text,600),image:v[k].image,...(k==='printBanner'?{link:v[k].link}:{})};}
if(out.detailingPlans.length>12||out.detailingPlans.some(p=>!str(p.name)||!safeURL(p.image)||!Array.isArray(p.features)||p.features.length>20)||out.ppfPlans.length>12)throw Error('Check service plans');await save(env.DB,'services_v2',out);return json({saved:true});
}catch(e){return json({error:e.message||'Could not save'},400);}}
